def compute(vars):
    new_growth = vars["v1"]
    old_growth = vars["v2"]
    change = new_growth - old_growth
    return {
        "value": change,
        "trace": {
            "new_growth": new_growth,
            "old_growth": old_growth,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage points"
            }
        }
    }
